 import { MeshBasicNodeMaterial } from 'three/webgpu';
import {
  uv,
  vec2,
  vec4,
  color,
  mix,
  smoothstep,
  fract,
  sin,
  dot,
  mul,
  texture,
  float,
} from 'three/tsl';

export default function createNode(config, ctx) {
  const { Group, PlaneGeometry, Mesh, SRGBColorSpace } = ctx.THREE;

  const root = new Group();
  root.userData.handlers = {};
  root.userData.timelines = [];

  const palette = {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10',
  };

  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const textItem = items.find((i) => i.role === 'headline') ?? items[0] ?? { text: 'Get started' };
  const fontSize = textItem.typography?.fontSize ?? 42;

  const planeW = 2.0;
  const planeH = 0.62;
  const geometry = new PlaneGeometry(planeW, planeH);

  const u = uv();
  const grad = mix(color(palette.ink), color(palette.surface), smoothstep(float(0), float(1), u.y));
  const noise = fract(mul(sin(dot(u, vec2(12.9898, 78.233))), 43758.5453));
  const grain = mix(grad, color(palette.paper), mul(noise, 0.045));

  const surfaceMaterial = new MeshBasicNodeMaterial({ transparent: true });
  surfaceMaterial.colorNode = vec4(grain, 1);

  const surfaceMesh = new Mesh(geometry, surfaceMaterial);
  root.add(surfaceMesh);

  const accentGeo = new PlaneGeometry(0.7, 0.03);
  const accentMat = new MeshBasicNodeMaterial({ transparent: true });
  accentMat.colorNode = vec4(color(palette.accent), 1);
  const accentBar = new Mesh(accentGeo, accentMat);
  accentBar.position.set(0, -0.12, 0.015);
  root.add(accentBar);

  const label = ctx.fontAtlas.createText(String(textItem.text || 'Get started'), {
    fontSize,
    color: palette.paper,
    align: 'center',
  });
  label.position.z = 0.02;
  root.add(label);

  let mapTex = null;

  if (config.imageUrl) {
    ctx.textureLoader
      .loadTexture(config.imageUrl)
      .then((tex) => {
        tex.colorSpace = SRGBColorSpace;
        mapTex = tex;

        const texNode = texture(tex, u).rgb;
        const mapped = mix(texNode, grad, 0.55);
        const mappedGrain = mix(mapped, color(palette.paper), mul(noise, 0.05));

        surfaceMaterial.colorNode = vec4(mappedGrain, 1);
        surfaceMaterial.needsUpdate = true;
      })
      .catch(() => {});
  }

  root.userData.cleanup = () => {
    root.userData.timelines.forEach((t) => {
      if (t && typeof t.kill === 'function') t.kill();
    });
    root.userData.timelines.length = 0;

    geometry.dispose();
    surfaceMaterial.dispose();
    accentGeo.dispose();
    accentMat.dispose();

    if (mapTex) {
      mapTex.dispose();
      mapTex = null;
    }

    root.traverse((obj) => {
      if (obj.geometry && obj.geometry !== geometry && obj.geometry !== accentGeo) {
        obj.geometry.dispose();
      }
      if (obj.material && obj.material !== surfaceMaterial && obj.material !== accentMat) {
        if (Array.isArray(obj.material)) {
          obj.material.forEach((m) => m.dispose());
        } else {
          obj.material.dispose();
        }
      }
    });
  };

  return root;
}
